const express = require('express');
const { S3Client, GetObjectCommand } = require('@aws-sdk/client-s3');
const { tokenAuth } = require('../middleware/token');

const app = express();
const s3 = new S3Client({ region: 'us-east-1' });

app.get('/cache/:hash', tokenAuth, async (req, res) => {
  const { hash } = req.params;
  const projectScope = req.headers['x-monorepo-scope'] || '@shared/common';

  // Verify that the authenticated token grants access to the requested package scope
  if (!req.user.permittedScopes?.includes(projectScope)) {
    return res.status(403).json({ error: 'Access denied: Token not authorized for requested project scope' });
  }

  try {
    const s3Response = await s3.send(new GetObjectCommand({
      Bucket: process.env.CACHE_S3_BUCKET,
      Key: `${projectScope}/${hash}.tar.gz`
    }));

    res.setHeader('Content-Type', 'application/gzip');
    s3Response.Body.pipe(res);
  } catch (err) {
    res.status(404).json({ error: 'Artifact not found' });
  }
});

module.exports = app;
